import { ViewTradeDetails } from '@/Components/Feature/Backend/User/ViewTradeDetails';
import { Badge } from '@/Components/UI/Badge';
import { useTranslations } from '@/Hooks/useTranslations';
import type { CrudConfig, CrudPageProps } from '@/Types/crud';

export function useTradeConfig(props: CrudPageProps): CrudConfig {

    const modelProperty = props?.modelProperty;
    const routePrefix = modelProperty?.routePrefix;

    const advanceFilterOptions = props?.advanceFilterOptions || [];

    const { t } = useTranslations();

    const baseBreadcrumbs = [
        { label: 'Dashboard', href: route('backend.dashboard') },
        { label: 'Trades', href: route(`${routePrefix}.index`) },
    ];

    return {
        resource: 'trade',
        resourcePlural: 'trades',
        title: 'Trades',
        description: 'All user trades',

        routes: {
            index: `${routePrefix}.index`,
            show: `${routePrefix}.show`,
        },

        viewDisplayMode: 'modal',
        viewDialogConfig: {
            size: 'xl',
            showStats: true,
            showErrors: true,
            showDownloadButton: false,
            title: t('View'),
            description: t('Trade details'),
            viewComponent: ViewTradeDetails,
        },

        table: {
            selectable: false,
            searchable: true,
            sortable: false,
            serializable: true,

            searchPlaceholder: 'Search user, crypto...',

            columns: [

                {
                    key: 'user',
                    label: 'User',
                    render: (row: any) => (
                        <div className="flex flex-col">
                            <span className="font-medium">{row?.user?.name}</span>
                            <span className="text-xs text-gray-500">{row?.user?.email}</span>
                        </div>
                    )
                },

                // CRYPTO
                {
                    key: 'crypto',
                    label: 'Crypto',
                    render: (row: any) => (
                        <div className="flex items-center gap-2">
                            <img
                                src={row?.crypto?.images?.thumb}
                                className="w-5 h-5 rounded-full"
                            />
                            <span>{row?.crypto?.symbol}</span>
                        </div>
                    )
                },

                // Group 2: Direction + Duration → "Trade"
                {
                    key: 'trade',
                    label: 'Trade',
                    render: (row: any) => {
                        const isLong = row.direction === 'long';
                        return (
                            <div className="flex flex-col gap-0.5">
                                <Badge className={isLong ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}>
                                    {isLong ? 'LONG' : 'SHORT'}
                                </Badge>
                                <span className="text-xs text-gray-500">{row.duration_seconds}s</span>
                            </div>
                        );
                    }
                },

                // Group 3: Amount + P/L → "Financials"
                {
                    key: 'financials',
                    label: 'Financials',
                    render: (row: any) => {
                        const isProfit = !row.profit_loss.includes('-');
                        return (
                            <div className="flex flex-col gap-0.5">
                                <span className="text-sm font-medium">{row.amount}</span>
                                <span className={isProfit ? 'text-xs text-green-600 font-medium' : 'text-xs text-red-600 font-medium'}>
                                    P/L: {row.profit_loss}
                                </span>
                            </div>
                        );
                    }
                },

                // Group 4: Result + Status → "Outcome"
                {
                    key: 'outcome',
                    label: 'Outcome',
                    render: (row: any) => {
                        const resultMap: any = {
                            win: 'bg-green-100 text-green-700',
                            lose: 'bg-red-100 text-red-700',
                            pending: 'bg-yellow-100 text-yellow-700',
                        };
                        const statusMap: any = {
                            open: 'bg-blue-100 text-blue-700',
                            closed: 'bg-gray-100 text-gray-700',
                            cancelled: 'bg-yellow-100 text-yellow-700',
                        };
                        return (
                            <div className="flex flex-col gap-1">
                                <span className={`px-2 py-0.5 text-xs rounded ${resultMap[row.result]}`}>
                                    {row.result?.toUpperCase()}
                                </span>
                                <span className={`px-2 py-0.5 text-xs rounded ${statusMap[row.status]}`}>
                                    {row.status?.toUpperCase()}
                                </span>
                            </div>
                        );
                    }
                },

                // Group 5: Open price + Close price + Win % → "Prices"
                {
                    key: 'prices',
                    label: 'Prices',
                    render: (row: any) => (
                        <div className="flex flex-col gap-0.5 text-xs">
                            <span><span className="text-gray-400">{t('Open')}:</span> {row.open_price}</span>
                            <span><span className="text-gray-400">{t('Close')}:</span> {row.close_price}</span>
                            <span><span className="text-gray-400">{t('Win')}:</span> {Number(row.win_pct_applied).toFixed(2)}%</span>
                        </div>
                    )
                },

                // Group 6: Opened at + Closes at + Closed at + Created at → "Timeline"
                {
                    key: 'timeline',
                    label: 'Timeline',
                    render: (row: any) => (
                        <div className="flex flex-col gap-0.5 text-xs">
                            <span><span className="text-gray-400">{t('Opened')}:</span> {row.opened_at}</span>
                            <span><span className="text-gray-400">{t('Closes')}:</span> {row.closes_at}</span>
                            {row.closed_at && (
                                <span><span className="text-gray-400">{t('Closed')}:</span> {row.closed_at}</span>
                            )}
                            <span className="text-gray-400 mt-0.5">{t('Created')}:</span> {row.created_at}
                        </div>
                    )
                },



            ]
        },

        filters: {
            searchFields: ['username', 'email', 'phone', 'ip_address'],
            filterFields: advanceFilterOptions,
        },

        breadcrumbs: {
            index: baseBreadcrumbs,
        },

        permissions: {
            actions: {
                view: 'trade.view',
            },
        },

        labels: {
            singular: 'Trade',
            plural: 'Trades',
            key: 'trade',
        }
    };
}